function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const change_ev = multisetDiff(before.change_ev, after.change_ev);
  const sent = multisetDiff(before.sent, after.sent);
  const subscriber = multisetDiff(before.subscriber, after.subscriber);
  return {
    rels: [
      { rel: "change_ev", add: change_ev.add, del: change_ev.del },
      { rel: "sent", add: sent.add, del: sent.del },
      { rel: "subscriber", add: subscriber.add, del: subscriber.del },
    ],
    carryPending: sent.add.length > 0 || sent.del.length > 0,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) =>
      forkJoin([resolveSent_0Writes(seam, before, arrivals), resolveSent_1Writes(seam, before, arrivals)]).pipe(map((groups) => groups.flat())).pipe(
        concatMap((statements) => seam.runner.batch(seam.db, statements)),
        map(() => before),
      ),
    ),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // unmarked_edge_replays_backlog: engine.pl process_occurrences -> level_closure -> boundary_deltas.
}

